function canonEvent(){if(state.canonSeen.includes(state.worldYear))return null;const year=state.worldYear;if(year===68){const uchiha=state.clan==='Uchiha'&&state.village==='Konohagakure';return{title:'A noite do massacre Uchiha',canonYear:year,text:uchiha?'A tragédia que atinge o clã Uchiha toma as ruas da Folha. Em meio ao caos, você precisa decidir como sobreviver; os acontecimentos centrais da história seguem seu curso.':'A notícia da tragédia do clã Uchiha se espalha pela Folha. A vila está em choque, e todos tentam entender o que acontecerá com os sobreviventes.',choices:uchiha?[{label:'Fugir da Folha com ajuda de um aliado',effect:'+4 intel,-4 bond',action:'rogue'},{label:'Procurar abrigo e proteger um sobrevivente',effect:'+4 bond,+2 renown'},{label:'Manter-se escondido até a vila se acalmar',effect:'+3 intel,+2 chakra'}]:[{label:'Acolher quem precisa de ajuda',effect:'+4 bond,+2 renown'},{label:'Ouvir os rumores sem se envolver',effect:'+3 intel,+2 energy'},{label:'Ajudar a vila a manter a calma',effect:'+3 bond,+2 renown'}]};}const moments={70:{title:'A invasão durante o Exame Chūnin',text:'Durante o exame, uma aliança inimiga ataca a Folha. O período de provas vira uma luta para proteger moradores e companheiros.',choices:[{label:'Ajudar a evacuar a área',effect:'+4 bond,+2 renown'},{label:'Observar e levar informações ao comando',effect:'+4 intel,+2 renown'},{label:'Ficar ao lado da equipe',effect:'+3 taijutsu,+3 bond'}]},72:{title:'A partida de Sasuke',text:'Sasuke deixa a vila em busca de poder. Amigos e líderes discutem como trazê-lo de volta sem esquecer os riscos.',choices:[{label:'Apoiar a equipe de resgate',effect:'+3 taijutsu,+3 bond'},{label:'Ajudar a planejar a busca',effect:'+4 intel,+2 renown'},{label:'Respeitar a escolha dele, mesmo discordando',effect:'+4 bond,+2 intel'}]},76:{title:'O ataque de Pain',text:'A Folha é atingida por uma força devastadora. A prioridade é salvar vidas e ajudar a vila a se reerguer.',choices:[{label:'Resgatar moradores',effect:'+5 bond,+3 renown,-8 energy'},{label:'Levar suprimentos aos feridos',effect:'+4 renown,+2 intel'},{label:'Defender um ponto de evacuação',effect:'+3 taijutsu,+3 renown,-8 energy'}]},78:{title:'A Quarta Guerra Shinobi',text:'As grandes vilas se unem diante de uma ameaça comum. Sua experiência pode fazer diferença na proteção da aliança.',choices:[{label:'Lutar ao lado da aliança',effect:'+4 taijutsu,+4 renown,-10 energy'},{label:'Coordenar informações e estratégia',effect:'+5 intel,+3 renown'},{label:'Proteger aliados e civis',effect:'+5 bond,+3 renown'}]}};const moment=moments[year];return moment?{...moment,canonYear:year}:null;}function nextEvent(){const canon=canonEvent();if(canon)return canon;const pool=eventPool();let idx=Math.floor(Math.random()*pool.length);if(pool.length>1&&idx===state.eventIndex)idx=(idx+1)%pool.length;state.eventIndex=idx;const e=pool[idx];return{title:e[0],text:e[1],choices:e.slice(2).map(s=>{const [label,effect]=s.split('|');return{label,effect}})};}
const actions=[
{icon:'◈',title:'Treinar',hint:'Aprimore uma habilidade',run(){const skills=['taijutsu','ninjutsu','chakra'];const sk=skills[Math.floor(Math.random()*skills.length)];state[sk]+=5;state.energy-=14;return `Treino intenso: +5 ${skillLabel(sk)}.`}},
{icon:'⌕',title:'Estudar',hint:'Conhecimento e estratégia',run(){state.intel+=5;state.energy-=7;return'Você estudou táticas e teoria ninja. +5 inteligência.'}},
{icon:'♡',title:'Conviver',hint:'Fortaleça uma amizade',run(){let r=state.relations[Math.floor(Math.random()*state.relations.length)];r.value=clamp(r.value+9);state.bond+=3;state.energy-=4;return`Um bom momento com ${r.name}. +9 amizade.`}},
{icon:'⚑',title:'Fazer missão',hint:'Ganhe ryō e reputação',run(){if(state.age<12)return null;let success=state.intel+state.taijutsu+state.ninjutsu+state.chakra>150;state.ryo+=state.rogue?(success?35:18):(success?28:12);state.renown+=success?5:2;state.energy-=22;return state.rogue?(success?'Trabalho clandestino concluído. +35 ryō; sua fama entre nukenin cresce.':'O trabalho clandestino foi difícil. +18 ryō e você escapou.'):(success?'Missão concluída com mérito. +28 ryō, +5 reputação.':'A missão foi complicada, mas voltou em segurança. +12 ryō, +2 reputação.')}},
{icon:'⌂',title:'Descansar',hint:'Recupere energia',run(){state.energy=clamp(state.energy+27);state.bond+=1;return'Um dia tranquilo devolveu suas forças. +27 energia.'}},
{icon:'◉',title:'Explorar',hint:'Descubra algo inesperado',run(){const finds=['Você ouviu histórias de viajantes. +2 inteligência.','Um comerciante pagou por sua ajuda. +18 ryō.','Encontrou um lugar calmo para meditar. +4 chakra.','Ajudou um morador e ganhou sua confiança. +3 reputação.'];let n=Math.floor(Math.random()*finds.length);if(n===0)state.intel+=2;if(n===1)state.ryo+=18;if(n===2)state.chakra+=4;if(n===3)state.renown+=3;state.energy-=5;return finds[n]}},
 {icon:'⚔',title:'Combater',hint:'Treine em um duelo por turnos',run(){return startCombat()}}
];
function startCombat(){const names=state.rogue?['Caçador de recompensas','Ninja rastreador','Mercenário da fronteira']:['Rival da Academia','Ninja renegado','Desafiante da vila'];const name=names[Math.floor(Math.random()*names.length)];const max=48+Math.min(38,Math.floor(state.age*.65));state.combat={name,health:max,maxHealth:max,power:9+Math.floor(state.age/5),guard:false};state.energy-=8;return`Você iniciou um duelo contra ${name}. Escolha seus movimentos.`;}function combatTurn(move){const b=state.combat;if(!b)return;let text='';if(move==='fugir'){state.health=Math.max(1,state.health-3);state.combat=null;text='Você encerrou o duelo e recuou. -3 vitalidade.';}else{if(move==='atacar'){const damage=9+Math.floor(state.taijutsu*.24)+Math.floor(Math.random()*7);b.health=Math.max(0,b.health-damage);text=`Seu ataque acerta e causa ${damage} de dano.`;}else if(move==='jutsu'){if(state.chakraPoints<12){toast('Você precisa de 12 pontos de chakra para usar um jutsu.');return}state.chakraPoints-=12;const damage=12+Math.floor(state.ninjutsu*.3)+Math.floor(Math.random()*9);b.health=Math.max(0,b.health-damage);text=`Seu jutsu acerta e causa ${damage} de dano. -12 chakra.`;}else{state.chakraPoints=clamp(state.chakraPoints+9);b.guard=true;text='Você assume uma postura defensiva e recupera 9 chakra.';}if(b.health<=0){state.combat=null;state.ryo+=16;state.renown+=3;state.taijutsu+=1;state.energy=clamp(state.energy-4);text+=` Vitória! +16 ryō, +3 reputação e +1 taijutsu.`;}else{let damage=Math.max(3,b.power+Math.floor(Math.random()*7)-Math.floor(state.taijutsu*.09));if(b.guard)damage=Math.ceil(damage*.35);state.health=Math.max(0,state.health-damage);b.guard=false;text+=` ${b.name} contra-ataca e causa ${damage} de dano.`;if(state.health<=0){state.health=12;state.combat=null;state.energy=clamp(state.energy-12);text+=' Você foi derrotado e recuou com ajuda da equipe. Vitalidade recuperada até 12.';}}}addJournal(text);save();render();toast(text);}function setRogue(){if(state.rogue)return;state.rogue=true;state.bond=clamp(state.bond-8);state.renown+=2;addJournal(`Você abandonou ${state.village} e passou a viver como ninja rogue (nukenin).`);save();}function becomeRogue(){if(state.rogue)return;if(confirm(`Abandonar ${state.village} e se tornar um ninja rogue (nukenin)? Essa escolha muda suas missões e sua vida na vila.`)){setRogue();render();toast('Você agora é um nukenin. Sua antiga vila pode enviar perseguidores.');}}function doAction(i){if(state.combat){toast('Conclua o combate atual antes de fazer outra atividade.');return}if(state.finished||state.activities>=2||(state.energy<5&&i!==4)){ toast(state.activities>=2?'Você já aproveitou suas duas atividades deste ano.':'Energia baixa — tente descansar.');return}const result=actions[i].run();if(!result){toast('Missões ninja ficam disponíveis a partir dos 12 anos.');return}state.activities++;state.energy=clamp(state.energy);state.ryo=Math.max(0,state.ryo);addJournal(result);save();render();toast(result)}
function applyEffect(effect){for(const part of effect.split(',')){const m=part.match(/^([+-])(\d+)\s+(\w+)$/);if(!m)continue;const amount=Number(m[2])*(m[1]==='-'?-1:1),key=m[3];if(key==='ryo')state.ryo=Math.max(0,state.ryo+amount);else if(key==='energy')state.energy=clamp(state.energy+amount);else if(key==='bond'){state.bond=clamp(state.bond+amount);if(state.relations.length)state.relations[0].value=clamp(state.relations[0].value+Math.ceil(amount/2))}else state[key]=clamp((state[key]||0)+amount)} }

