 function availableCharacters(year){return characterTimeline.filter(character=>year>=character.debut&&(character.end===undefined||year<character.end)).map(character=>({...character,value:25,power:characterPower[character.name]||700}))}
 function randomAffinity(clan){const inherited=chakraAffinityByClan[clan];const affinities=Object.keys(jutsusByAffinity);return inherited&&Math.random()<.75?inherited:affinities[Math.floor(Math.random()*affinities.length)]}
 function powerLevel(){return Math.round(8*((Number(state.chakra)||0)+(Number(state.taijutsu)||0)+(Number(state.ninjutsu)||0)+(Number(state.intel)||0)))}
 function hasClanLineage(clan){return Boolean(clan&&(state?.clan===clan||(state?.lineage||[]).some(ancestor=>ancestor.clan===clan)))}
-function allJutsus(){const affinity=jutsusByAffinity[state?.chakraAffinity]||[];const clanJutsus=hasClanLineage(state?.clan)?(jutsusByClan[state.clan]||[]):[];return [...affinity.map(jutsu=>({...jutsu,category:'Afinidade'})),...clanJutsus.map(jutsu=>({...jutsu,category:`Clã ${state.clan}`,clan:state.clan}))]}
+function allJutsus(){const affinity=jutsusByAffinity[state?.chakraAffinity]||[];const lineages=[...new Set([state?.clan,...(state?.lineage||[]).map(ancestor=>ancestor.clan)].filter(Boolean))];const clanJutsus=lineages.flatMap(clan=>hasClanLineage(clan)?(jutsusByClan[clan]||[]).map(jutsu=>({...jutsu,category:`Clã ${clan}`,clan})):[]);return [...affinity.map(jutsu=>({...jutsu,category:'Afinidade'})),...clanJutsus]}
 function meetsJutsuRequirements(jutsu){if(jutsu.intel!==undefined&&(Number(state?.intel)||0)<jutsu.intel)return false;if(jutsu.requirements&&!Object.entries(jutsu.requirements).every(([key,value])=>(Number(state?.[key])||0)>=value))return false;return !jutsu.clan||hasClanLineage(jutsu.clan)}
 function unlockedJutsus(){return allJutsus().filter(meetsJutsuRequirements)}
 function jutsuRequirementText(jutsu){return jutsu.requirements?Object.entries(jutsu.requirements).map(([key,value])=>`${({taijutsu:'taijutsu',ninjutsu:'ninjutsu',chakra:'chakra',intel:'inteligência'})[key]||key} ${value}`).join(' · '):`inteligência ${jutsu.intel}`}
 function syncJutsuUnlocks(){state.jutsuKnown??=[];const unlocked=unlockedJutsus();const fresh=unlocked.filter(jutsu=>!state.jutsuKnown.includes(jutsu.id));state.jutsuKnown=[...new Set([...state.jutsuKnown,...unlocked.map(jutsu=>jutsu.id)])];return fresh}

