 defesa especial':''}.`;}b.guard=false;if(state.health<=0){state.health=12;state.combat=null;state.energy=clamp(state.energy-12);text+=' Você foi derrotado e recuou com ajuda da equipe. Vitalidade recuperada até 12.';}}}if(state.combat){state.combat.log=text;state.combat.turn=(state.combat.turn||0)+1;}addJournal(text,'Combate');save();render();toast(text)}
 function updateBattleJutsuButton(){const select=$('#battle-jutsu');const button=$('#battle-use-jutsu');if(!select||!button)return;const jutsu=unlockedJutsus().find(item=>item.id===select.value);button.disabled=!jutsu||state.chakraPoints<jutsuCost(jutsu)}
 function renderBattleScreen(){const battle=state.combat;const jutsus=unlockedJutsus();$('#game').innerHTML=`<div class="battle-screen"><div class="battle-heading"><div class="eyebrow">Duelo shinobi · ${escapeHtml(eraLabel())}</div><h1>${escapeHtml(state.name)} contra ${escapeHtml(battle.name)}</h1><p class="subtitle">Ano ${state.worldYear} · ${state.age} anos · Turno ${(battle.turn||0)+1}</p></div><div class="battle-arena"><article class="fighter-card player"><h2>${escapeHtml(state.name)}</h2><div class="fighter-power">Força ${powerLevel().toLocaleString('pt-BR')} · ${escapeHtml(state.clan)}</div><div class="battle-health"><i style="width:${clamp(state.health)}%"></i></div><div class="battle-resource">Vitalidade ${state.health}/100 · Chakra ${state.chakraPoints}/100</div></article><article class="fighter-card opponent"><h2>${escapeHtml(battle.name)}</h2><div class="fighter-power">Força ${Number(battle.power||0).toLocaleString('pt-BR')}</div><div class="battle-health"><i style="width:${Math.max(0,battle.health/battle.maxHealth*100)}%"></i></div><div class="battle-resource">Vitalidade ${battle.health}/${battle.maxHealth} PV</div></article></div><div class="battle-log" aria-live="polite">${escapeHtml(battle.log||'O duelo começou. Escolha sua ação.')}</div><div class="battle-controls"><button onclick="combatTurn('atacar')">Atacar</button><button onclick="combatTurn('defender')">Defender e concentrar chakra</button><div class="battle-technique"><select id="battle-jutsu" onchange="updateBattleJutsuButton()" ${jutsus.length?'':'disabled'}>${jutsus.length?jutsus.map(jutsu=>`<option value="${escapeHtml(jutsu.id)}">${escapeHtml(jutsu.name)} · ${jutsuCost(jutsu)} chakra</option>`).join(''):'<option>Treine para desbloquear técnicas</option>'}</select><button id="battle-use-jutsu" onclick="combatTurn('jutsu',$('#battle-jutsu')?.value)" ${jutsus.length?'':'disabled'}>Usar técnica selecionada</button></div><button class="battle-escape" onclick="combatTurn('fugir')">Encerrar duelo e recuar</button></div><div class="battle-footer">As técnicas de clã exigem linhagem e atributos. O custo é verificado a cada turno.</div></div>`;updateBattleJutsuButton()}
 '''
